import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    try:
        stringDeserializer = __import__('yaml')
        tempload = lambda t: stringDeserializer.load(t, Loader=stringDeserializer.Loader)
        data = tempload(ip_address)
        ip = data.get('ip', '')
    except:
        return 'Invalid IP address received'

    if re.fullmatch(IP_REGEX, str(ip)):
        parts = ip.split('.')
        if all(0 <= int(part) <= 255 for part in parts):
            return ip

    return 'Invalid IP address received'

